const now=new Date();
let state=loadState();let role='viewer';let sessionPin='';let cloudSaveTimer;let currentMonth=new Date(now.getFullYear(),now.getMonth(),1);let selectedDay=now.getDate();let filter='active';
function loadState(){try{const s=JSON.parse(localStorage.getItem(STORE_KEY));if(s?.employees)return s}catch{}return{employees:INITIAL_EMPLOYEES,settings:{restTarget:8,minStaff:3},schedules:{}}}
async function cloudRequest(name,body){const response=await fetch(`${SUPABASE_URL}/rest/v1/rpc/${name}`,{method:'POST',headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error('cloud request failed');return response.json()}
async function loadCloud(pin){const data=await cloudRequest('load_schedule',{p_password:pin});if(!data?.employees)throw new Error('invalid cloud data');state=data;localStorage.setItem(STORE_KEY,JSON.stringify(state))}
function save(){localStorage.setItem(STORE_KEY,JSON.stringify(state));if(role!=='admin'||!sessionPin)return;clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(()=>cloudRequest('save_schedule',{p_password:sessionPin,p_data:state}).catch(()=>showToast('雲端儲存失敗，請檢查網路')),350)}
function monthKey(){return `${currentMonth.getFullYear()}-${String(currentMonth.getMonth()+1).padStart(2,'0')}`}
function daysInMonth(){return new Date(currentMonth.getFullYear(),currentMonth.getMonth()+1,0).getDate()}
function schedule(){const key=monthKey();state.schedules[key]??={};return state.schedules[key]}
function isRest(id,day){return schedule()[id]?.includes(day)||false}
function setRest(id,day,value){const s=schedule();s[id]??=[];s[id]=value?[...new Set([...s[id],day])]:s[id].filter(d=>d!==day);save();renderAll()}
function activeFulltime(){return state.employees.filter(e=>e.active&&e.type==='fulltime')}
function restCount(id){return (schedule()[id]||[]).length}
function staffOnDay(day){return activeFulltime().length-activeFulltime().filter(e=>isRest(e.id,day)).length}
function warningDays(){let n=0;for(let d=1;d<=daysInMonth();d++)if(staffOnDay(d)<state.settings.minStaff)n++;return n}
function showToast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2200)}
function enter(nextRole){role=nextRole;document.querySelector('#login').hidden=true;document.querySelector('#app').hidden=false;document.querySelectorAll('.admin-only').forEach(el=>el.hidden=role!=='admin');renderAll()}
document.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();const pin=document.querySelector('#pin');const error=document.querySelector('#pin-error');const button=e.currentTarget.querySelector('button');const nextRole=pin.value==='8888'?'admin':pin.value==='1688'?'viewer':null;if(!nextRole){error.textContent='密碼不正確，請重新輸入。';error.hidden=false;pin.setAttribute('aria-invalid','true');pin.select();pin.focus();return}button.disabled=true;button.textContent='連接雲端中…';try{await loadCloud(pin.value);sessionPin=pin.value;error.hidden=true;pin.removeAttribute('aria-invalid');enter(nextRole)}catch{error.textContent='無法連接雲端，請檢查網路後重試。';error.hidden=false;pin.setAttribute('aria-invalid','true')}finally{button.disabled=false;button.textContent='登入'}});
document.querySelector('#logout').addEventListener('click',()=>{sessionPin='';document.querySelector('#app').hidden=true;document.querySelector('#login').hidden=false;const pin=document.querySelector('#pin');pin.value='';pin.removeAttribute('aria-invalid');document.querySelector('#pin-error').hidden=true;pin.focus()});
const titles={dashboard:'本月總覽',calendar:'月曆班表',summary:'整月總表',employees:'員工管理',settings:'排班設定'};
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item,.page').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector(`#${b.dataset.page}`).classList.add('active');document.querySelector('#page-title').textContent=titles[b.dataset.page];window.scrollTo({top:0,behavior:'smooth'})}));
document.querySelectorAll('[data-month]').forEach(b=>b.addEventListener('click',()=>{currentMonth=new Date(currentMonth.getFullYear(),currentMonth.getMonth()+Number(b.dataset.month),1);selectedDay=1;renderAll()}));
function renderAll(){renderDashboard();renderCalendar();renderSummary();renderEmployees();renderSettings()}
function renderDashboard(){const full=activeFulltime();const target=state.settings.restTarget;document.querySelector('#month-label').textContent=`${currentMonth.getFullYear()} 年 ${currentMonth.getMonth()+1} 月`;document.querySelector('#fulltime-count').textContent=full.length;document.querySelector('#goal-count').textContent=full.filter(e=>restCount(e.id)>=target).length;document.querySelector('#warning-count').textContent=warningDays();document.querySelector('#goal-list').innerHTML=full.map(e=>{const count=restCount(e.id),pct=Math.min(100,count/target*100);return `<div class="goal-row"><div class="avatar">${e.name.slice(-1)}</div><div class="goal-info"><strong>${e.name}</strong><small>${e.start}–${e.end}</small><div class="progress" aria-label="已休 ${count} 天，共 ${target} 天"><span style="width:${pct}%"></span></div></div><span class="goal-value ${count<target?'missing':''}">${count}/${target}</span></div>`}).join('')||'<p class="muted">尚無正職員工。</p>'}
document.querySelector('#auto-schedule').addEventListener('click',()=>{const full=activeFulltime(),target=state.settings.restTarget,maxOff=Math.max(0,full.length-state.settings.minStaff);if(!full.length||maxOff===0){showToast('最低人數設定過高，無法自動排休');return}const key=monthKey();state.schedules[key]={};let cursor=0;for(const e of full){state.schedules[key][e.id]=[];let tries=0;while(state.schedules[key][e.id].length<target&&tries<daysInMonth()*3){const day=(cursor%daysInMonth())+1;const offToday=full.filter(x=>(state.schedules[key][x.id]||[]).includes(day)).length;if(offToday<maxOff)state.schedules[key][e.id].push(day);cursor+=2;tries++}cursor++}save();renderAll();showToast('已產生建議排休，請再確認人力')});
function renderCalendar(){const year=currentMonth.getFullYear(),month=currentMonth.getMonth();document.querySelector('#calendar-title').textContent=`${year} 年 ${month+1} 月`;const first=new Date(year,month,1).getDay();let html='';for(let i=0;i<first;i++)html+='<span class="calendar-day blank"></span>';for(let d=1;d<=daysInMonth();d++){const off=activeFulltime().filter(e=>isRest(e.id,d)).length;const today=year===now.getFullYear()&&month===now.getMonth()&&d===now.getDate();html+=`<button class="calendar-day ${today?'today':''} ${selectedDay===d?'selected':''} ${staffOnDay(d)<state.settings.minStaff?'warning':''}" data-day="${d}" aria-label="${month+1}月${d}日，${off}人休假"><span>${d}</span>${off?`<span class="off-count">休 ${off}</span>`:''}</button>`}document.querySelector('#calendar-grid').innerHTML=html;document.querySelectorAll('.calendar-day[data-day]').forEach(b=>b.addEventListener('click',()=>{selectedDay=Number(b.dataset.day);renderCalendar()}));renderDayDetail()}
function renderDayDetail(){const date=`${currentMonth.getMonth()+1} 月 ${selectedDay} 日`;const warning=staffOnDay(selectedDay)<state.settings.minStaff;document.querySelector('#day-detail').innerHTML=`<h3>${date}</h3><p class="${warning?'field-error':'muted'}">正職到班 ${staffOnDay(selectedDay)} 人／最低 ${state.settings.minStaff} 人${warning?'，人力不足':''}</p>${activeFulltime().map(e=>`<div class="day-person"><div><strong>${e.name}</strong><div class="muted">${e.start}–${e.end}</div></div><button class="${isRest(e.id,selectedDay)?'rest':''}" data-toggle-rest="${e.id}" ${role!=='admin'?'disabled':''}>${isRest(e.id,selectedDay)?'休假':'上班'}</button></div>`).join('')}`;document.querySelectorAll('[data-toggle-rest]').forEach(b=>b.addEventListener('click',()=>setRest(b.dataset.toggleRest,selectedDay,!isRest(b.dataset.toggleRest,selectedDay))))}
function renderSummary(){const days=daysInMonth(),full=activeFulltime();document.querySelector('#summary-month-label').textContent=`${currentMonth.getFullYear()} 年 ${currentMonth.getMonth()+1} 月`;let html='<thead><tr><th class="name-cell" scope="col">姓名</th>';for(let d=1;d<=days;d++)html+=`<th scope="col">${d}</th>`;html+='<th class="total-cell" scope="col">休</th></tr></thead><tbody>';for(const e of full){html+=`<tr><th class="name-cell" scope="row">${e.name}</th>`;for(let d=1;d<=days;d++){const rest=isRest(e.id,d);html+=`<td><button class="roster-cell ${rest?'rest':''}" data-roster-id="${e.id}" data-roster-day="${d}" aria-label="${e.name} ${currentMonth.getMonth()+1}月${d}日 ${rest?'休假':'上班'}" ${role!=='admin'?'disabled':''}>${rest?'休':'·'}</button></td>`}html+=`<td class="total-cell">${restCount(e.id)}</td></tr>`}html+='</tbody>';document.querySelector('#roster-table').innerHTML=html;document.querySelectorAll('[data-roster-id]').forEach(b=>b.addEventListener('click',()=>setRest(b.dataset.rosterId,Number(b.dataset.rosterDay),!isRest(b.dataset.rosterId,Number(b.dataset.rosterDay)))))}
document.querySelector('#clear-schedule').addEventListener('click',()=>{if(confirm('要清除這個月所有排休嗎？')){state.schedules[monthKey()]={};save();renderAll();showToast('本月排休已清除')}});
function renderEmployees(){const items=state.employees.filter(e=>filter==='all'||e.active);document.querySelector('#employee-list').innerHTML=items.map(e=>`<article class="employee-card ${e.active?'':'inactive'}"><div class="avatar">${e.name.slice(-1)}</div><div><h3>${e.name} <small>${e.type==='fulltime'?'正職':'PT'}</small></h3><p>${e.start}–${e.end}${e.note?` · ${e.note}`:''}</p></div><div class="employee-actions admin-only" ${role!=='admin'?'hidden':''}><button class="mini-button" data-edit="${e.id}" aria-label="編輯 ${e.name}">編輯</button><button class="mini-button" data-active="${e.id}" aria-label="${e.active?'停用':'恢復'} ${e.name}">${e.active?'停用':'恢復'}</button></div></article>`).join('');document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>openEmployee(b.dataset.edit)));document.querySelectorAll('[data-active]').forEach(b=>b.addEventListener('click',()=>{const e=state.employees.find(x=>x.id===b.dataset.active);e.active=!e.active;save();renderAll();showToast(e.active?'員工已恢復':'員工已停用，舊班表仍保留')}))}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderEmployees()}));
const dialog=document.querySelector('#employee-dialog');function openEmployee(id){const e=state.employees.find(x=>x.id===id);document.querySelector('#dialog-title').textContent=e?'編輯員工':'新增員工';document.querySelector('#employee-id').value=e?.id||'';document.querySelector('#employee-name').value=e?.name||'';document.querySelector('#employee-type').value=e?.type||'fulltime';document.querySelector('#start-time').value=e?.start||'09:00';document.querySelector('#end-time').value=e?.end||'21:00';document.querySelector('#employee-note').value=e?.note||'';dialog.showModal()}
document.querySelector('#add-employee').addEventListener('click',()=>openEmployee());document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());document.querySelector('#employee-form').addEventListener('submit',e=>{e.preventDefault();const id=document.querySelector('#employee-id').value;const data={name:document.querySelector('#employee-name').value.trim(),type:document.querySelector('#employee-type').value,start:document.querySelector('#start-time').value,end:document.querySelector('#end-time').value,note:document.querySelector('#employee-note').value.trim()};if(!data.name)return;const found=state.employees.find(x=>x.id===id);if(found)Object.assign(found,data);else state.employees.push({id:`e${Date.now()}`,...data,active:true});save();dialog.close();renderAll();showToast('員工資料已儲存')});
function renderSettings(){document.querySelector('#rest-target').value=state.settings.restTarget;document.querySelector('#min-staff').value=state.settings.minStaff;document.querySelectorAll('#settings-form input').forEach(x=>x.disabled=role!=='admin')}
document.querySelector('#settings-form').addEventListener('submit',e=>{e.preventDefault();state.settings.restTarget=Number(document.querySelector('#rest-target').value);state.settings.minStaff=Number(document.querySelector('#min-staff').value);save();renderAll();showToast('排班設定已儲存')});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
setInterval(async()=>{if(role!=='viewer'||!sessionPin||document.querySelector('#app').hidden)return;try{await loadCloud(sessionPin);renderAll()}catch{}},30000);

